import gazetteer from '@/lib/visitor-cities.json';
import { haversineKm, type Coordinate } from '@/lib/geo-distance';

/**
 * Every city in the world above 15,000 people, generated by
 * `npm run cities:gazetteer` from GeoNames and committed.
 *
 * Two jobs, both about turning an IP lookup into a name a person recognises:
 *
 * 1. Canonicalise. The database may say `Nis`, `NIS` or `Niš`; the page should
 *    say what the feed says.
 * 2. Correct. When the lookup lands on a village, the nearest real city is what
 *    the visitor would name — see `findNearestCity`.
 */

/** `[name, countryCode, latitude, longitude, population]` */
type Row = [string, string, number, number, number];

export type GazetteerCity = {
  name: string;
  countryCode: string;
  coordinate: Coordinate;
  population: number;
};

const CITIES = (((gazetteer as { cities?: unknown })?.cities) ?? []) as Row[];

/**
 * Matching key: accents folded, punctuation to spaces. Stricter than `cityKey`,
 * which keeps punctuation, because `Co. Meath` and `Co Meath` are one place and
 * a GeoNames name may carry an apostrophe the database does not.
 */
function placeKey(value: string): string {
  return value
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    // Lowercased before the letters below are folded: `Łódź` starts with a
    // capital, and a case-sensitive replace left it as `łódź` while the query
    // `Lodz` became `lodz`. The two never met.
    .toLowerCase()
    // NFKD does not decompose these, so `København` and `Kobenhavn` would
    // otherwise be two different keys and a Danish visitor unplaceable.
    .replace(/ø/g, 'o')
    .replace(/ł/g, 'l')
    .replace(/đ|ð/g, 'd')
    .replace(/ß/g, 'ss')
    .replace(/æ/g, 'ae')
    .replace(/œ/g, 'oe')
    .replace(/þ/g, 'th')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function toCity(row: Row): GazetteerCity {
  return {
    name: row[0],
    countryCode: row[1],
    coordinate: { latitude: row[2], longitude: row[3] },
    population: row[4],
  };
}

/** Built once per process: ~34,000 rows is a few milliseconds, not a per-request cost. */
let nameIndex: Map<string, Row[]> | null = null;

function getNameIndex(): Map<string, Row[]> {
  if (nameIndex) return nameIndex;

  const index = new Map<string, Row[]>();
  for (const row of CITIES) {
    const key = placeKey(row[0]);
    if (!key) continue;

    const bucket = index.get(key);
    if (bucket) bucket.push(row);
    else index.set(key, [row]);
  }

  nameIndex = index;
  return index;
}

/**
 * The city with this name, preferring the visitor's own country — `Paris` in
 * France before Paris, Texas — and the largest place when the country is not
 * known. `null` means the gazetteer has no such city, which is what makes a
 * village a village.
 */
function pickByName(name: string, countryCode?: string | null): GazetteerCity | null {
  const matches = getNameIndex().get(placeKey(name));
  if (!matches || matches.length === 0) return null;

  const wanted = countryCode?.trim().toUpperCase();
  const sameCountry = wanted ? matches.filter((row) => row[1] === wanted) : [];
  const pool = sameCountry.length > 0 ? sameCountry : matches;

  const best = pool.reduce((winner, row) => (row[4] > winner[4] ? row : winner), pool[0]);
  return toCity(best);
}

/**
 * The city with this name, preferring the visitor's own country — `Paris` in
 * France before Paris, Texas — and the largest place when the country is not
 * known.
 *
 * `City` is the one suffix the databases disagree about. GeoNames files New York
 * as `New York City`; MaxMind, Vercel and a person on the phone all say
 * `New York`. Matching the short form and keeping the caller's spelling means
 * the page says what the visitor would say, while the coordinates still come
 * from the entry that exists.
 *
 * `null` means the gazetteer has no such city, which is what makes a village a
 * village.
 */
export function findCityByName(name: string | null | undefined, countryCode?: string | null): GazetteerCity | null {
  if (!name?.trim()) return null;

  const spelling = name.replace(/\s+/g, ' ').trim();

  const direct = pickByName(spelling, countryCode);
  if (direct) return direct;

  const withoutSuffix = spelling.replace(/\s+\b(City|Town)\b$/i, '').trim();
  const withSuffix = /\b(City|Town)$/i.test(spelling) ? spelling : `${spelling} City`;

  for (const variant of [withSuffix, withoutSuffix]) {
    if (!variant || variant === spelling) continue;

    const match = pickByName(variant, countryCode);
    if (match) return { ...match, name: spelling };
  }

  return null;
}

/**
 * The nearest city to a coordinate, optionally limited to one country.
 *
 * The country bound is not a detail: without it a village in southern Serbia
 * snaps to a Bulgarian or Kosovan town, and the rail then names a city across a
 * border. A bounding box first, then the exact great-circle distance, so this
 * stays linear over a filtered slice instead of all 34,000 rows.
 */
export function findNearestCity(
  coordinate: Coordinate | null | undefined,
  options: { countryCode?: string | null; maxKm?: number } = {},
): { city: GazetteerCity; distanceKm: number } | null {
  if (!coordinate) return null;
  if (!Number.isFinite(coordinate.latitude) || !Number.isFinite(coordinate.longitude)) return null;

  const maxKm = options.maxKm ?? 75;
  const wanted = options.countryCode?.trim().toUpperCase() || null;

  // 1 degree of latitude is ~111.32 km everywhere; longitude shrinks with the
  // cosine of latitude, floored so the box cannot collapse at the poles.
  const latitudeDelta = maxKm / 111.32;
  const longitudeDelta = maxKm / (111.32 * Math.max(Math.cos((coordinate.latitude * Math.PI) / 180), 0.01));

  let best: { city: GazetteerCity; distanceKm: number } | null = null;

  for (const row of CITIES) {
    if (wanted && row[1] !== wanted) continue;
    if (Math.abs(row[2] - coordinate.latitude) > latitudeDelta) continue;
    if (Math.abs(row[3] - coordinate.longitude) > longitudeDelta) continue;

    const distanceKm = haversineKm(coordinate, { latitude: row[2], longitude: row[3] });
    if (distanceKm > maxKm) continue;

    // A smaller distance always wins; a tie goes to the larger place, so a
    // suburb never shadows the city it belongs to.
    if (!best || distanceKm < best.distanceKm - 0.001
      || (Math.abs(distanceKm - best.distanceKm) <= 0.001 && row[4] > best.city.population)) {
      best = { city: toCity(row), distanceKm };
    }
  }

  return best;
}

export function gazetteerSize(): number {
  return CITIES.length;
}
